def _phi_tetra_box(x, s, c, h) -> float:
    """解析判据 φ（见模块文档）。只用算术。"""
    upper = max(x[i] - c[i] - h[i] for i in range(3))
    lower = sum(max(0.0, c[i] - h[i] - x[i]) for i in range(3)) - s
    return max(upper, lower)

