    """闭线段间距离（不相交时在某条的端点处实现；内联算术，只作邻近筛选）。"""
    def pd(p, u, v):
        ex, ey = v[0] - u[0], v[1] - u[1]
        t = max(0.0, min(1.0, ((p[0] - u[0]) * ex + (p[1] - u[1]) * ey) / (ex * ex + ey * ey)))
        return math.hypot(p[0] - u[0] - t * ex, p[1] - u[1] - t * ey)
    return min(pd(a, c, d), pd(b, c, d), pd(c, a, b), pd(d, a, b))

