    c, sn = math.cos(yaw), math.sin(yaw)
    top = box(center=(0.0, 0.0, 1.0 + gap), half=(0.5, 0.5, 0.5))
    A = Polyhedron([(c * x - sn * y, sn * x + c * y, z) for x, y, z in top.verts], list(top.faces))
    return A, box(half=(0.5, 0.5, 0.5))

